class TestSumOfEvenNumbers(unittest.TestCase):
    def test_basic_even_sum(self):
        """Test the function with a simple list containing even numbers."""
        self.assertEqual(
            solution([2, 4, 6, 8]),
            20
        )

    def test_empty_list(self):
        """Test the function with an empty list (should return 0)."""
        self.assertEqual(
            solution([]),
            0
        )

    def test_all_odd_numbers(self):
        """Test the function with a list that contains only odd numbers."""
        self.assertEqual(
            solution([1, 3, 5, 7, 9]),
            0
        )

    def test_negative_even_numbers(self):
        """Test the function with negative even numbers."""
        self.assertEqual(
            solution([-2, -4, -6, -8]),
            -20
        )

    def test_mixed_positive_negative_zero(self):
        """Test with a mix of positives, negatives, evens, odds, and zero."""
        self.assertEqual(
            solution([0, 1, 2, -3, -4, 5, 6]),
            8  # 0 + 2 + (-4) + 6 = 4? Wait compute: 0+2-4+6=4. Let's recalc: 0+2-4+6=4. So correct sum 4.
        )

    def test_large_numbers_and_max_length(self):
        """Test with the maximum allowed list length (100) and large even numbers."""
        # Create a list of 100 even numbers: 1000, 998, ..., 802
        large_even_list = [1000 - 2 * i for i in range(100)]
        expected_sum = sum(large_even_list)
        self.assertEqual(
            solution(large_even_list),
            expected_sum
        )

    def test_non_integer_elements(self):
        """Test the function with non-integer elements; should raise TypeError."""
        with self.assertRaises(TypeError):
            solution([1, 2.5, 3, 4])

    def test_none_input(self):
        """Test the function with None as input; should raise TypeError."""
        with self.assertRaises(TypeError):
            solution(None)

    def test_string_input(self):
        """Test the function with a string instead of a list; should raise TypeError."""
        with self.assertRaises(TypeError):
            solution("not a list")

