        """Verify that large integers are summed correctly."""
        big_vals = [10**12, 10**12 + 1, 10**12 + 2]
        self.assertEqual(solution(big_vals), 3 * 10**12 + 3)

    def test_single_element(self):
        """Check that a single integer returns itself."""
        self.assertEqual(solution([42]), 42)

    def test_100_elements(self):
        """Test maximum allowed size: 100 consecutive integers."""
        lst = list(range(100))
        expected_sum = sum(lst)
        self.assertEqual(solution(lst), expected_sum)

