        """Input containing a string should trigger the error message."""
        result = solution([1, "two", 3])
        self.assertEqual(result, "Invalid input, please provide a list of integers.")
        self.assertIsInstance(result, str)

    def test_invalid_float(self):
        """Input containing a float should trigger the error message."""
        result = solution([1, 2.5, 3])
        self.assertEqual(result, "Invalid input, please provide a list of integers.")

