def solution():
    import sys
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])

    # Recursive function that sums a range [start, end].
    # For small ranges (size <= 10) it uses a loop for efficiency
    # and to demonstrate the use of loops alongside recursion.
    def sum_range(start, end):
        if start > end:
            return 0
        if end - start <= 10:
            total = 0
            for i in range(start, end + 1):
                total += i
            return total
        mid = (start + end) // 2
        return sum_range(start, mid) + sum_range(mid + 1, end)

    result = sum_range(1, n)
    sys.stdout.write(str(result))

