import unittest

class TestFibonacciFunction(unittest.TestCase):
    """
    Test suite for the Fibonacci sequence implementation.
    The function under test is assumed to be named `function_to_test` and
    accepts a single integer argument n (0 ≤ n ≤ 30).
    """

    def test_base_case_zero(self):
        """F(0) should be 0."""
        self.assertEqual(solution(0), 0)

    def test_base_case_one(self):
        """F(1) should be 1."""
        self.assertEqual(solution(1), 1)

    def test_small_values(self):
        """Test small Fibonacci numbers."""
        expected = {2: 1, 3: 2, 5: 5, 8: 21}
        for n, value in expected.items():
            with self.subTest(n=n):
                self.assertEqual(solution(n), value)

    def test_medium_value(self):
        """Test a medium Fibonacci number."""
        self.assertEqual(solution(10), 55)

    def test_large_value(self):
        """Test the largest allowed Fibonacci number (n=30)."""
        self.assertEqual(solution(30), 832040)

    def test_output_type(self):
