def solution(n):
    """
    Return the nth Fibonacci number (0-indexed: F(0)=0, F(1)=1).
    Raises ValueError for negative input.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 0
    if n == 1:
        return 1
    prev, curr = 0, 1
    for _ in range(1, n):
        prev, curr = curr, prev + curr
    return curr

