def solution():
    """
    Reads an integer n from standard input, computes the n-th Fibonacci number
    using an iterative dynamic programming approach, prints the result,
    and returns it. The function handles the constraints 0 ≤ n ≤ 30.
    """
    import sys

    # Read input, strip whitespace, and convert to integer
    data = sys.stdin.readline().strip()
    if not data:
        return  # No input provided

    try:
        n = int(data)
    except ValueError:
        raise ValueError("Input must be an integer.")

    # Validate constraints
    if n < 0 or n > 30:
        raise ValueError("n must satisfy 0 ≤ n ≤ 30.")

    # Base cases
    if n == 0:
        result = 0
    elif n == 1:
        result = 1
    else:
        # Iterative DP: maintain only the last two Fibonacci numbers
        prev, curr = 0, 1
        for _ in range(2, n + 1):
            prev, curr = curr, prev + curr
        result = curr

    # Output the result
    print(result)

    # Return the result for potential downstream use
    return result

