def solution():
    """
    Implements a simple stack that supports push, pop, and top operations.
    Reads input from stdin where each line is a call in the form:
        push(x)
        pop()
        top()
    For each pop() or top() call, prints the result or an error message
    if the stack is empty.
    """
    import sys
    stack = []

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue

        if line.startswith("push"):
            # Extract integer inside parentheses
            try:
                val = int(line[line.find("(")+1 : line.find(")")])
            except (ValueError, IndexError):
                # Malformed push; ignore or could raise an error
                continue
            stack.append(val)
        elif line == "pop()":
            if stack:
                sys.stdout.write(str(stack.pop()) + "\n")
            else:
                sys.stdout.write("Error: Stack is empty\n")
        elif line == "top()":
            if stack:
                sys.stdout.write(str(stack[-1]) + "\n")
            else:
                sys.stdout.write("Error: Stack is empty\n")
        else:
            # Unknown operation; ignore
            continue

