    """
    Recursively compute the sum of all integers in a nested list.

    Parameters:
    nested_list (list): A list that may contain integers or other lists.

    Returns:
    int: The total sum of all integers in the nested structure.
    """
    def helper(lst):
        total = 0
        for element in lst:
            if isinstance(element, int):
                total += element
            else:
                # Assume the element is a list; recurse into it
                total += helper(element)
        return total

    return helper(nested_list)

