        int: The total sum of all integers in the nested structure.
    """
    def helper(lst):
        total = 0
        for element in lst:
            if isinstance(element, int):
                total += element
            elif isinstance(element, list):
                total += helper(element)
            else:
                # Non-integer, non-list element found
                raise TypeError(f"Unsupported element type: {type(element).__name__}")
        return total

    if not isinstance(nested_list, list):
        raise TypeError("Input must be a list")
    return helper(nested_list)

class TestSumOfElementsInRecursiveList(unittest.TestCase):
