def solution():
    """
    Reads an integer n from standard input and returns the sum of all natural numbers from 1 to n.
    Uses a simple recursive function to compute the sum. Recursion depth is limited to 1000
    by default, so we increase the recursion limit to safely handle the maximum input value.
    """
    import sys
    # Ensure recursion limit is sufficient for n up to 1000
    sys.setrecursionlimit(2000)

    # Read input
    data = sys.stdin.read().strip()
    if not data:
        return None  # No input provided

    n = int(data)

    def recursive_sum(k: int) -> int:
        """Return sum of numbers from 1 to k using recursion."""
        if k <= 1:
            return k
        return k + recursive_sum(k - 1)

    return recursive_sum(n)

