def solution(arr, target):
    """
    Perform recursive binary search on a sorted list `arr` to find `target`.
    Returns the index of `target` if found, otherwise returns -1.

    Parameters:
    - arr: List[int] – Sorted list of unique integers (ascending order).
    - target: int – Value to search for in `arr`.

    Returns:
    - int – Index of `target` in `arr`, or -1 if `target` is not present.
    """
    def recursive_search(left, right):
        # Base case: interval is empty
        if left > right:
            return -1
        mid = left + (right - left) // 2
        # Check middle element
        if arr[mid] == target:
            return mid
        # Decide which half to search next
        if target < arr[mid]:
            return recursive_search(left, mid - 1)
        else:
            return recursive_search(mid + 1, right)

    # Edge case: empty array
    if not arr:
        return -1
    return recursive_search(0, len(arr) - 1)

