def solution():
    import sys

    # Read the integer n from standard input
    data = sys.stdin.read().strip()
    if not data:
        return
    try:
        n = int(data)
    except ValueError:
        # If the input is not a valid integer, we simply return
        return

    # Base cases for Fibonacci sequence
    if n == 0:
        print(0)
        return
    if n == 1:
        print(1)
        return

    # Use iterative dynamic programming to compute F(n) efficiently
    a, b = 0, 1  # a = F(0), b = F(1)
    for _ in range(2, n + 1):
        a, b = b, a + b  # Shift the window
    print(b)

