def solution():
    import sys, bisect
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    try:
        n = int(next(it))
    except StopIteration:
        return
    arr = [int(next(it)) for _ in range(n)]
    try:
        target = int(next(it))
    except StopIteration:
        target = None
    # Sort the list
    arr.sort()
    # Find leftmost occurrence of target
    idx = bisect.bisect_left(arr, target)
    if idx < n and arr[idx] == target:
        # Output 1-based index as per example
        print(idx + 1)
    else:
        print(-1)

