        """Test the example from the problem statement."""
        self.assertEqual(solution([1, 2, 3, 4, 5]), 6)

    def test_all_even(self):
        """All elements are even; every pair sum is even."""
        self.assertEqual(solution([2, 4, 6]), 3)

    def test_all_odd(self):
        """All elements are odd; every pair sum is even."""
        self.assertEqual(solution([1, 3, 5]), 3)

    def test_mixed_parity_single_pair(self):
        """Mix of even and odd; only one valid pair."""
        self.assertEqual(solution([1, 2]), 0)

    def test_mixed_parity_multiple_pairs(self):
        """Mix of even and odd; two valid pairs."""
        # Pairs: (1,3), (2,4)
        self.assertEqual(solution([1, 2, 3, 4]), 2)

    def test_negative_numbers(self):
        """Negative numbers with parity considered."""
        # Pairs: (-1,-3) -> even; others odd
        self.assertEqual(solution([-1, -2, -3]), 1)

    def test_single_element(self):
        """Array with a single element should yield zero pairs."""
        self.assertEqual(solution([7]), 0)

    def test_duplicates(self):
        """Multiple identical elements; all pairs are valid."""
        self.assertEqual(solution([2, 2, 2, 2]), 6)

    def test_all_zeros(self):
        """Zero is even; all pairs are valid."""
        self.assertEqual(solution([0, 0, 0, 0]), 6)

    def test_stress_random(self):
        """Large random array; compare with brute force calculation."""
        arr = [random.randint(-100000, 100000) for _ in range(1000)]
        expected = sum(
            1 for i in range(len(arr))
            for j in range(i + 1, len(arr))
            if (arr[i] + arr[j]) % 2 == 0
        )
