        """Test with maximum allowed n (1000) and all elements odd."""
        arr = [1] * 1000
        expected = 1000 * 999 // 2
        self.assertEqual(solution(arr), expected)

    def test_boundary_n_one(self):
        """Test with minimum allowed n (1)."""
        self.assertEqual(solution([42]), 0)

