def solution(s: str) -> int:
    """
    Return the index of the first unique (non‑repeating) character in a lowercase string.
    If the string is empty or has no unique characters, return -1.
    """
    if not s:
        return -1

    # Count occurrences of each letter (a–z)
    freq = [0] * 26
    for ch in s:
        freq[ord(ch) - 97] += 1

    # Find the first character whose frequency is exactly 1
    for idx, ch in enumerate(s):
        if freq[ord(ch) - 97] == 1:
            return idx

    return -1

