def solution(nums):
    """
    Returns a new list containing only the even integers from `nums`, sorted in ascending order.
    Raises TypeError if `nums` is not an iterable of integers.
    """
    if nums is None:
        raise TypeError("Input cannot be None")
    # Ensure all elements are integers
    for x in nums:
        if not isinstance(x, int):
            raise TypeError(f"All elements must be integers, got {type(x)}")
    even_numbers = [x for x in nums if x % 2 == 0]
    # Use built-in sorting algorithm (TimSort) which is efficient for this problem size
    return sorted(even_numbers)

