def solution(array1, array2, target):
    """
    Merge two sorted arrays and perform a binary search for the target.

    Parameters
    ----------
    array1 : list[int]
        First sorted array (non‑decreasing order).
    array2 : list[int]
        Second sorted array (non‑decreasing order).
    target : int
        Value to search for in the merged array.

    Returns
    -------
    int
        Index of target in the merged array if found, otherwise -1.
    """
    # Merge the two sorted arrays using two‑pointer technique.
    merged = []
    i, j = 0, 0
    n1, n2 = len(array1), len(array2)
    while i < n1 and j < n2:
        if array1[i] <= array2[j]:
            merged.append(array1[i])
            i += 1
        else:
            merged.append(array2[j])
            j += 1
    # Append remaining elements from array1 or array2.
    if i < n1:
        merged.extend(array1[i:])
    if j < n2:
        merged.extend(array2[j:])

    # Recursive binary search helper.
    def binary_search(left, right):
        if left > right:
            return -1
        mid = (left + right) // 2
        mid_val = merged[mid]
        if mid_val == target:
            return mid
        elif mid_val < target:
            return binary_search(mid + 1, right)
        else:
            return binary_search(left, mid - 1)

    return binary_search(0, len(merged) - 1)

