        """Compute LIS length by O(n^2) DP (suitable for small n)."""
        if not arr:
            return 0
        n = len(arr)
        dp = [1] * n
        for i in range(n):
            for j in range(i):
                if arr[j] < arr[i]:
                    dp[i] = max(dp[i], dp[j] + 1)
