def solution(nums, target):
    """
    Search for `target` in a rotated sorted array that may contain duplicates.
    Returns the index if found, otherwise -1.
    The algorithm uses an adapted binary search that handles duplicates.
    """
    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2

        # Direct hit
        if nums[mid] == target:
            return mid

        # If we cannot determine which side is sorted due to duplicates,
        # shrink the search window.
        if nums[left] == nums[mid] == nums[right]:
            left += 1
            right -= 1
            continue

        # Left half is sorted
        if nums[left] <= nums[mid]:
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        # Right half is sorted
        else:
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1

