import unittest

class TestCoinChangeCombinations(unittest.TestCase):
    """Unit tests for the coin change combinations problem."""

    def _dp(self, amount, coins):
        """Reference dynamic programming implementation to compute expected results."""
        ways = [0] * (amount + 1)
        ways[0] = 1
        for coin in coins:
            for amt in range(coin, amount + 1):
                ways[amt] += ways[amt - coin]
        return ways[amount]

    def test_basic_example(self):
        """Test the basic example from the problem statement."""
        self.assertEqual(solution(5, [1, 2, 5]), 4)

    def test_no_combination(self):
        """Test a case with no possible combinations."""
        self.assertEqual(solution(3, [2]), 0)

