        """Test that amount zero returns exactly one combination (no coins)."""
        for coins in ([1], [2, 5], [1, 2, 5], [100, 200, 300]):
            self.assertEqual(solution(0, coins), 1)

    def test_single_coin_even_amount(self):
        """Test a single coin that divides the amount evenly."""
        self.assertEqual(solution(5000, [2]), 1)

    def test_single_coin_odd_amount(self):
        """Test a single coin that does not divide the amount."""
        self.assertEqual(solution(5001, [2]), 0)

