def solution():
    """
    Reads two lines from standard input:
      1) A Python-like list of integers, e.g. [10, 20, 30]
      2) A Python-like list of operation strings, e.g. ["add", "divide", "subtract"]

    Performs the operations sequentially on a running total.  
    The first element of the array is used as the initial total.  
    For each operation, the next element of the array is taken as the operand.
    If the array is shorter than the number of operations, the array is wrapped
    around in a circular fashion.

    Supported operations:
      - "add"      : total += operand
      - "subtract" : total -= operand
      - "multiply" : total *= operand
      - "divide"   : total = total // operand  (integer division)

    Any division by zero results in an error message.
    If an unknown operation string is encountered, an error message is returned.

    The function returns a dictionary:
      - {"result": <final integer>} on success
      - {"message": <error string>} on failure
    """
    import sys, ast

    data = sys.stdin.read().strip().splitlines()
    if len(data) < 2:
        return {"message": "Invalid input format"}

    try:
        array = ast.literal_eval(data[0].strip())
        ops   = ast.literal_eval(data[1].strip())
    except Exception as e:
        return {"message": f"Parsing error: {e}"}

    # Validate array
    if not isinstance(array, list) or not array:
        return {"message": "Array must be a non-empty list"}
    for v in array:
        if not isinstance(v, int):
            return {"message": "Array elements must be integers"}
    # Validate ops
    if not isinstance(ops, list):
        return {"message": "Operations must be a list"}
    for op in ops:
        if op not in {"add", "subtract", "multiply", "divide"}:
            return {"message": f"Unsupported operation: {op}"}

    # Core computation
    total = array[0]
    n = len(array)
    idx = 1  # next operand index
    for op in ops:
        operand = array[idx % n]
        idx += 1
        try:
            if op == "add":
                total += operand
            elif op == "subtract":
                total -= operand
            elif op == "multiply":
                total *= operand
            elif op == "divide":
                if operand == 0:
                    return {"message": "Division by zero error"}
                total = int(total / operand)  # integer division, same as // but handles negatives
        except Exception as e:
            return {"message": f"Unexpected error: {e}"}

    return {"result": total}

def solution(array, ops):
    """
    Applies a sequence of operations to a running total derived from the input array.

    Parameters
    ----------
    array : list[int]
        List of integers. Must contain at least one element; the first element
        is used as the initial value of the running total.
    ops : list[str]
        List of operation names. Each element must be one of:
        "add", "subtract", "multiply", "divide".

    Returns
    -------
    dict
        On success: {"result": <final integer>}
        On error:   {"message": <error string>}
    """
    # Validate array
    if not isinstance(array, list) or not array:
        return {"message": "Array must be a non-empty list"}
    if not all(isinstance(v, int) for v in array):
        return {"message": "Array elements must be integers"}

    # Validate ops
    if not isinstance(ops, list):
        return {"message": "Operations must be a list"}
    allowed_ops = {"add", "subtract", "multiply", "divide"}
    for op in ops:
        if op not in allowed_ops:
            return {"message": f"Unsupported operation: {op}"}

    # Perform operations
    total = array[0]
    n = len(array)
    idx = 1  # next operand index in array

    for op in ops:
        operand = array[idx % n]
        idx += 1

        if op == "add":
            total += operand
        elif op == "subtract":
            total -= operand
        elif op == "multiply":
            total *= operand
        elif op == "divide":
            if operand == 0:
                return {"message": "Division by zero error"}
            total //= operand

    return {"result": total}

