import unittest
import random
import copy

def solution(arr):
    """
    Classify a list of integers into counts of positive, negative, and zero values.

    Parameters
    ----------
    arr : list[int]
        List of integers to classify.

    Returns
    -------
    dict
        Dictionary with keys 'positive', 'negative', and 'zero' containing the counts.
    """
    # Validate input type
    if not isinstance(arr, list):
        raise TypeError("Input must be a list of integers")
    # Validate each element
    for item in arr:
        if not isinstance(item, int):
            raise TypeError("All elements in the list must be integers")

    counts = {'positive': 0, 'negative': 0, 'zero': 0}
    for num in arr:
        if num > 0:
            counts['positive'] += 1
        elif num < 0:
            counts['negative'] += 1
        else:
            counts['zero'] += 1
    return counts


