import unittest
import random

class TestEvenOddSum(unittest.TestCase):
    def test_single_zero(self):
        """Single element that is zero should return True as even sum equals odd sum."""
        self.assertTrue(solution([0]))

    def test_single_even(self):
        """Single even element: even sum equals odd sum (both zero)."""
        self.assertTrue(solution([2]))

    def test_single_odd(self):
        """Single odd element: odd sum non‑zero, even sum zero -> should be False."""
        self.assertFalse(solution([1]))

    def test_all_zero_array(self):
        """Array composed entirely of zeros: even sum 0, odd sum 0 -> True."""
        self.assertTrue(solution([0, 0, 0, 0]))

    def test_equal_sums_simple(self):
        """A simple case where sums of even and odd numbers are equal."""
        self.assertTrue(solution([2, 4, 1, 5]))

    def test_equal_sums_with_negative(self):
        """Even and odd sums equal even when negative numbers are involved."""
        self.assertTrue(solution([10, -10, 7, -7]))

    def test_equal_sums_with_large_numbers(self):
        """Test equality on large magnitude numbers."""
        self.assertTrue(solution([1000000, -1000000, 500001, -500001]))

    def test_not_equal_sums_all_odd(self):
        """All numbers are odd: even sum is zero, odd sum non‑zero -> False."""
        self.assertFalse(solution([1, 3, 5, 7]))

    def test_not_equal_sums_all_even(self):
        """All numbers are even: even sum non‑zero, odd sum is zero -> False."""
        self.assertFalse(solution([2, 4, 6, 8]))

    def test_random_large_array(self):
        """Stress test with a large random array; compare result to a direct computation."""
        # Generate 100,000 random integers in the allowed range
        arr = [random.randint(-10000, 10000) for _ in range(100_000)]
        expected = sum(x for x in arr if x % 2 == 0) == sum(x for x in arr if x % 2 != 0)
        self.assertEqual(solution(arr), expected)

    def test_zero_and_nonzero_mix(self):
        """Mix of zeros and non‑zero values where sums should be equal."""
        # Even sum: 0+4+2=6; Odd sum: 0+1+5=6
        self.assertTrue(solution([0, 4, 2, 0, 1, 5]))

    def test_large_even_odd_difference(self):
        """Large difference between sums; should return False."""
        arr = [10**4] * 50 + [1] * 50  # even sum huge, odd sum small
        self.assertFalse(solution(arr))

    def test_alternating_equal_sums(self):
        """Alternating even and odd values that balance out."""
        arr = []
        for i in range(1, 101):
            if i % 2 == 0:
                arr.append(i)          # even numbers
            else:
                arr.append(-i)         # odd numbers (negative to balance)
        self.assertTrue(solution(arr))

    def test_negative_and_positive_balancing(self):
        """Negative and positive numbers that cancel each other out."""
        arr = [3, -3, 2, -2, 5, -5]
        self.assertTrue(solution(arr))

    def test_performance_boundary(self):
        """Test the function with the maximum allowed number of elements."""
        n = 100_000
        arr = [i if i % 2 == 0 else -i for i in range(1, n + 1)]
        # Even sum: sum of even i; Odd sum: sum of -odd i
        expected = sum(i for i in range(1, n + 1) if i % 2 == 0) == sum(-i for i in range(1, n + 1) if i % 2 != 0)
        self.assertEqual(solution(arr), expected)

if __name__ == '__main__':
    unittest.main()

