def solution(arr):
    """
    Returns True if the sum of even numbers in arr equals the sum of odd numbers,
    otherwise returns False. Handles empty lists by returning True (both sums are zero).
    """
    sum_even = 0
    sum_odd = 0
    for num in arr:
        if num % 2 == 0:
            sum_even += num
        else:
            sum_odd += num
    return sum_even == sum_odd

