def solution(nums, target):
    """
    Search for `target` in a rotated sorted array `nums` of distinct integers.
    Returns the index of target if found, otherwise returns -1.
    Uses a modified binary search that runs in O(log n) time.
    """
    if not nums:
        return -1

    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2
        mid_val = nums[mid]

        if mid_val == target:
            return mid

        # Determine which side is properly sorted
        if nums[left] <= mid_val:
            # Left side [left, mid] is sorted
            if nums[left] <= target < mid_val:
                right = mid - 1  # Target lies in left sorted part
            else:
                left = mid + 1   # Search right part
        else:
            # Right side [mid, right] is sorted
            if mid_val < target <= nums[right]:
                left = mid + 1   # Target lies in right sorted part
            else:
                right = mid - 1  # Search left part

    return -1

def solution():
    """Maximize profit by selecting only non‑negative jobs.

    The problem reduces to summing all positive profits because
    each job is independent and we are free to skip any job.
    Negative values represent errors and are simply ignored.
    """
    import sys, ast

    data = sys.stdin.read()
    if not data:
        return 0

    # Try to parse an explicit list (e.g. "[3, -1, 2]") first
    profits = []
    if '[' in data:
        # Extract content between the first '[' and the last ']'
        try:
            start = data.index('[') + 1
            end = data.rindex(']')
            list_content = data[start:end]
            # Split on commas; strip whitespace
            for part in list_content.split(','):
                part = part.strip()
                if part:
                    profits.append(int(part))
        except Exception:
            # Fallback to token parsing if something goes wrong
            pass

    if not profits:
        # If list parsing failed or no brackets, fall back to token parsing
        tokens = data.split()
        if not tokens:
            return 0
        try:
            n = int(tokens[0])
        except ValueError:
            # If first token isn't an integer, treat all tokens as profits
            profits = list(map(int, tokens))
            n = len(profits)
        else:
            profits = list(map(int, tokens[1:1 + n]))

    # Sum only positive profits
    total_profit = sum(p for p in profits if p > 0)
    return total_profit

def solution(grid):
    """
    Compute the maximum path sum from the top-left to the bottom-right corner
    of a 2D grid moving only right or down. Return -1 if the grid is malformed
    (not a list of lists, contains non-integers, None, or values outside
    [-1000, 1000], or dimensions violate constraints).
    """
    # Validate that grid is a list
    if not isinstance(grid, list):
        return -1

    # Grid must not be empty
    if len(grid) == 0:
        return -1

    m = len(grid)  # number of rows

    # Validate row count constraint
    if m < 1 or m > 100:
        return -1

    # Determine number of columns from the first row
    if not isinstance(grid[0], list):
        return -1
    n = len(grid[0])

    # Validate column count constraint
    if n < 1 or n > 100:
        return -1

    # All rows must be lists of the same length
    for row in grid:
        if not isinstance(row, list):
            return -1
        if len(row) != n:
            return -1

    # Validate each cell for being an integer within the allowed range
    try:
        for i in range(m):
            for j in range(n):
                val = grid[i][j]
                if not isinstance(val, int):
                    return -1
                if val < -1000 or val > 1000:
                    return -1
    except Exception:
        # Any exception during validation indicates malformed input
        return -1

    # Dynamic programming to calculate maximum path sum
    # We can modify grid in place to store cumulative sums
    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0:
                # Start cell remains unchanged
                continue
            top = grid[i - 1][j] if i > 0 else float('-inf')
            left = grid[i][j - 1] if j > 0 else float('-inf')
            grid[i][j] += max(top, left)

    return grid[m - 1][n - 1]

def solution(grid):
    """
    Compute the maximum path sum from the top-left to the bottom-right corner
    of a 2D grid moving only right or down. Return -1 if the grid is malformed
    (not a list of lists, contains non-integers, None, or values outside
    [-1000, 1000], or dimensions violate constraints).  The function does
    not modify the input grid.
    """
    # Validate that grid is a list of lists
    if not isinstance(grid, list) or not grid:
        return -1

    m = len(grid)
    if m < 1 or m > 100:
        return -1

    # All rows must be lists of equal length
    n = None
    for r in grid:
        if not isinstance(r, list):
            return -1
        if n is None:
            n = len(r)
        elif len(r) != n:
            return -1
    if n is None or n < 1 or n > 100:
        return -1

    # Validate cell values
    for i in range(m):
        for j in range(n):
            v = grid[i][j]
            if not isinstance(v, int):
                return -1
            if v < -1000 or v > 1000:
                return -1

    # Dynamic programming using a separate table to avoid mutating input
    dp = [[0] * n for _ in range(m)]
    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0:
                dp[i][j] = grid[i][j]
            else:
                best_prev = -10**9
                if i > 0:
                    best_prev = max(best_prev, dp[i-1][j])
                if j > 0:
                    best_prev = max(best_prev, dp[i][j-1])
                dp[i][j] = grid[i][j] + best_prev

    return dp[m-1][n-1]

