def solution(operations):
    """
    Implements a custom stack with O(1) getMin operation.

    Parameters:
        operations (list of tuple): Each tuple represents an operation.
            ("push", x) – push value x onto the stack.
            ("pop",)     – pop the top element.
            ("top",)     – retrieve the top element.
            ("getMin",)  – retrieve the current minimum element.

    Returns:
        list: Results from 'top' and 'getMin' operations in the order they appear.
    """
    stack = []          # Main stack to hold all elements
    min_stack = []      # Auxiliary stack to hold the current minimum at each level
    results = []

    for op in operations:
        cmd = op[0]

        if cmd == "push":
            val = op[1]
            stack.append(val)
            if min_stack:
                min_stack.append(val if val < min_stack[-1] else min_stack[-1])
            else:
                min_stack.append(val)

        elif cmd == "pop":
            if stack:
                stack.pop()
                min_stack.pop()

        elif cmd == "top":
            if stack:
                results.append(stack[-1])
            else:
                results.append(None)

        elif cmd == "getMin":
            if min_stack:
                results.append(min_stack[-1])
            else:
                results.append(None)

    return results

