def solution(nums, target):
    # Merge sort implementation using recursion
    def merge_sort(arr):
        # Base case: single element is already sorted
        if len(arr) <= 1:
            return arr
        mid = len(arr) // 2
        # Recursively sort left and right halves
        left = merge_sort(arr[:mid])
        right = merge_sort(arr[mid:])
        # Merge the two sorted halves
        return merge(left, right)

    def merge(left, right):
        merged = []
        i = j = 0
        # Compare elements from both halves and append the smaller one
        while i < len(left) and j < len(right):
            if left[i] <= right[j]:
                merged.append(left[i])
                i += 1
            else:
                merged.append(right[j])
                j += 1
        # Append any remaining elements
        merged.extend(left[i:])
        merged.extend(right[j:])
        return merged

    # Binary search to find the first occurrence of target
    def binary_search_first(arr, tgt):
        left, right = 0, len(arr) - 1
        result = -1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] == tgt:
                result = mid
                # Continue searching in left half for earlier occurrence
                right = mid - 1
            elif arr[mid] < tgt:
                left = mid + 1
            else:
                right = mid - 1
        return result

    # Sort the array using merge sort
    sorted_nums = merge_sort(nums)

    # Perform binary search for the target value
    return binary_search_first(sorted_nums, target)

