    # Parse the list of N integers
    numbers_str = data[1].strip().split()
    if len(numbers_str) != N:
        return "Error: Invalid input"
    try:
        numbers = [int(x) for x in numbers_str]
    except ValueError:
        return "Error: Invalid input"
    # Parse target
    try:
        target = int(data[2].strip())
    except ValueError:
        return "Error: Invalid input"
    # Advanced sorting algorithm – using Python's built‑in Timsort
    # (fast, stable, O(n log n)). For the purpose of this challenge
    # we consider it an advanced sorting technique.
    sorted_numbers = sorted(numbers)
    # Binary search to find the target's index in the sorted list
    left, right = 0, N - 1
    result_index = -1
    while left <= right:
        mid = (left + right) // 2
        if sorted_numbers[mid] == target:
            result_index = mid
            break
        elif sorted_numbers[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return str(result_index)

