def solution(nums):
    """
    Recursively compute the sum of all positive even integers in the input list.

    Parameters:
        nums (list of int): List of integers to process.

    Returns:
        int: Sum of positive even numbers.
    """
    def helper(index):
        # Base case: if we've processed all elements, sum is 0
        if index == len(nums):
            return 0
        current = nums[index]
        # If current number is positive and even, include it in the sum
        if current > 0 and current % 2 == 0:
            return current + helper(index + 1)
        # Otherwise, skip it
        return helper(index + 1)

    return helper(0)

