def solution(n: int) -> int:
    """
    Return the factorial of a non‑negative integer n (0 ≤ n ≤ 20).
    Raises ValueError for negative inputs.
    Uses a simple recursive implementation which is safe for the
    given constraint (n <= 20).
    """
    if n < 0:
        raise ValueError("factorial not defined for negative integers")
    def _fact(k: int) -> int:
        if k == 0:
            return 1
        return k * _fact(k - 1)
    return _fact(n)

