    def _dp_expected(self, coins, amount):
        """Utility method to compute expected result using DP."""
        dp = [0] * (amount + 1)
        dp[0] = 1
        for coin in coins:
            for val in range(coin, amount + 1):
                dp[val] += dp[val - coin]
        return dp[amount]

    def test_amount_zero_returns_one(self):
        """The number of ways to make amount 0 should be 1 (no coins)."""
        self.assertEqual(solution([1, 2, 5], 0), 1)

