import unittest

class TestNestedParenthesesValidator(unittest.TestCase):
    def test_single_open_parenthesis(self):
        """A single '(' should be invalid."""
        self.assertFalse(solution('('))

    def test_single_close_parenthesis(self):
        """A single ')' should be invalid."""
        self.assertFalse(solution(')'))

    def test_basic_balanced_pair(self):
        """Simple pair '()' is valid."""
        self.assertTrue(solution('()'))

    def test_basic_nested_pair(self):
        """Nested pair '(())' is valid."""
        self.assertTrue(solution('(())'))

    def test_complex_balanced_string(self):
        """More complex but still valid: '(()())'."""
        self.assertTrue(solution('(()())'))

    def test_missing_closing_parenthesis(self):
        """Missing a closing parenthesis makes it invalid: '(()'."""
        self.assertFalse(solution('(()'))

    def test_missing_opening_parenthesis(self):
        """Missing an opening parenthesis makes it invalid: '())('."""
        self.assertFalse(solution('())('))

    def test_excess_closing_parenthesis(self):
        """Too many closing parentheses: '())'."""
        self.assertFalse(solution('())'))

    def test_long_balanced_string(self):
        """A long string of 50,000 opening followed by 50,000 closing parentheses."""
        large_balanced = '(' * 50000 + ')' * 50000
        self.assertTrue(solution(large_balanced))

    def test_long_unbalanced_string(self):
        """A long string with one fewer closing parenthesis."""
        large_unbalanced = '(' * 50000 + ')' * 49999
        self.assertFalse(solution(large_unbalanced))

    def test_alternating_valid_pattern(self):
        """Alternating '()' repeated many times is valid."""
        alternating = '()' * 50000
        self.assertTrue(solution(alternating))

    def test_alternating_invalid_pattern(self):
        """Alternating '()' with an extra '(' at the end is invalid."""
        alternating_invalid = '()' * 50000 + '('
        self.assertFalse(solution(alternating_invalid))

 def test_empty_string(self):
        """An empty string should be considered invalid as per problem constraints."""
        self.assertFalse(solution(''))

    def test_nested_deep_structure(self):
        """A deeply nested structure within size limits."""
        depth = 1000
        nested = '(' * depth + ')' * depth
        self.assertTrue(solution(nested))

    def test_random_complex_valid(self):
        """A pre-built complex but valid pattern."""
        pattern = '((()(()())())((()()()))(()()))'
        self.assertTrue(solution(pattern))

    def test_random_complex_invalid(self):
        """A pre-built complex but invalid pattern."""
        pattern = '((()(()())())((()()()))(()()'
        self.assertFalse(solution(pattern))

