    import sys, re, bisect
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    # first line: n
    try:
        n = int(data[0].strip())
    except:
        # if first line contains array only
        n = 0
    arr = []
    if len(data) >= 2:
        # second line may contain array in brackets or space separated
        line = data[1].strip()
        # remove brackets if present
        line = line.strip('[]')
        # split by comma or whitespace
        # replace commas with spaces and split
        line = line.replace(',', ' ')
        tokens = line.split()
        for tok in tokens:
            try:
                arr.append(int(tok))
            except:
                pass
    # In case array is given in multiple lines after first
    if len(arr) < n and len(data) > 2:
        for line in data[2:]:
            line = line.strip('[]')
            line = line.replace(',', ' ')
            tokens = line.split()
            for tok in tokens:
                try:
                    arr.append(int(tok))
