    # If n was not provided or mismatched, use whatever length arr has
    # Filter out negative numbers (they cannot be part of the increasing subsequence)
    filtered = [x for x in arr if x >= 0]
    # Compute length of LIS using patience sorting (O(n log n))
    tails = []
    for x in filtered:
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    print(len(tails))

