def solution(functions):
    """
    Executes a list of functions with provided data, handling errors.
    Returns a dictionary with results and formatted error messages.
    """
    import math

    # Define the supported functions
    def add(data):
        # Sum all integers in data
        return sum(data)

    def divide(data):
        # Expect exactly two numbers: numerator and denominator
        if len(data) < 2:
            raise ValueError("Insufficient data for division")
        numerator, denominator = data[0], data[1]
        if denominator == 0:
            # Custom message to match the required format
            raise ZeroDivisionError("Division by zero")
        return numerator / denominator

    def subtract(data):
        if not data:
            raise ValueError("No data provided")
        result =[0]
        for val in data[1:]:
            result -= val
        return result

    def multiply(data):
        prod = 1
        for val in data:
            prod *= val
        return prod

    def sqrt(data):
        if not data:
            raise ValueError("No data provided")
        val = data[0]
        if val < 0:
            raise ValueError("Negative input is not allowed")
        return math.sqrt(val)

    # Map function names to implementations
    func_map = {
        "add": add,
        "divide": divide,
        "subtract": subtract,
        "multiply": multiply,
        "sqrt": sqrt,
    }

    results = []
    errors = []

    for entry in functions:
        fn_name = entry.get("function_name")
        data = entry.get("data", [])
        func = func_map.get(fn_name)

        if func is None:
            # Unknown function name; treat as error
            results.append(None)
            errors.append(f"Error in {fn_name}: Unknown function")
            continue

        try:
            res = func(data)
            results.append(res)
        except Exception as e:
            results.append(None)
            # Use the exception message directly for clarity
            errors.append(f"Error in {fn_name}: {str(e)}")

    return {"results": results, "errors": errors}

