def solution(functions):
    """
    Executes a list of functions with provided data, handling errors.
    Returns a dictionary with two lists:
        - results: the computed value for each function (or None if an error occurred)
        - errors: error messages for calls that failed (empty string if successful)
    """
    import math

    # Supported operations ----------------------------------------------------
    def add(data):
        """Return the sum of all integers in data."""
        return sum(data)

    def divide(data):
        """Divide the first number by the second. Raises on insufficient data
        or division by zero."""
        if len(data) < 2:
            raise ValueError("Insufficient data for division")
        numerator, denominator = data[0], data[1]
        if denominator == 0:
            raise ZeroDivisionError("Division by zero")
        return numerator / denominator

    def subtract(data):
        """Subtract all subsequent numbers from the first."""
        if not data:
            raise ValueError("No data provided")
        result = data[0]
        for val in data[1:]:
            result -= val
        return result

    def multiply(data):
        """Return the product of all numbers in data."""
        prod = 1
        for val in data:
            prod *= val
        return prod

    def sqrt(data):
        """Return the square root of the first number. Raises on negative input."""
        if not data:
            raise ValueError("No data provided")
        val = data[0]
        if val < 0:
            raise ValueError("Negative input is not allowed")
        return math.sqrt(val)

    # Map function names to implementations ----------------------------------
    func_map = {
        "add": add,
        "divide": divide,
        "subtract": subtract,
        "multiply": multiply,
        "sqrt": sqrt,
    }

    # Execution loop ---------------------------------------------------------
    results = []
    errors = []

    for entry in functions:
        fn_name = entry.get("function_name")
        data = entry.get("data", [])
        func = func_map.get(fn_name)

        if func is None:
            # Unknown function name
            results.append(None)
            errors.append(f"Error in {fn_name}: Unknown function")
            continue

        try:
            res = func(data)
            results.append(res)
            errors.append("")  # No error for this entry
        except Exception as e:
            results.append(None)
            errors.append(f"Error in {fn_name}: {str(e)}")

    return {"results": results, "errors": errors}

