import unittest

class TestCoinChange(unittest.TestCase):
    """Unit tests for the coin change DP implementation (function_to_test)."""

    def test_basic_example_one(self):
        """Test the example with coins [1,2,5] and amount 5."""
        self.assertEqual(solution([1, 2, 5], 5), 4)

    def test_basic_example_two(self):
        """Test the example with coins [2] and amount 3 (no combinations)."""
        self.assertEqual(solution([2], 3), 0)

    def test_amount_zero(self):
        """Amount zero should always return 1 (empty combination)."""
        for coins in ([1], [2, 3], [5, 10, 20]):
            self.assertEqual(solution(coins, 0), 1)

    def test_large_amount_single_coin(self):
        """Only one coin type should produce exactly one combination for any amount."""
        self.assertEqual(solution([1], 5000), 1)

    def test_multiple_coins_large_amount(self):
        """Test a moderate coin set for amount 10."""
        self.assertEqual(solution([1, 2, 3, 4, 5], 10), 30)

    def test_unsorted_coins(self):
        """Order of coins should not affect the result."""
        self.assertEqual(solution([5, 2, 1], 5), 4)

    def test_duplicate_coins(self):
        """Duplicate denominations should not inflate the number of combinations."""
        self.assertEqual(solution([1, 1, 2], 3), 2)

    def test_large_coin_over_amount(self):
        """Coins larger than the amount should contribute zero combinations."""
        self.assertEqual(solution([10, 20], 5), 0)

    def test_amount_one(self):
        """Amount smaller than all coins should yield zero combinations."""
        self.assertEqual(solution([3, 4, 5], 1), 0)

    def test_complex_combination(self):
        """Test a mix of small and medium coins for a moderate amount."""
        self.assertEqual(solution([1, 3, 9], 12), 7)

    def test_large_numbers_in_coins(self):
        """Test coins with large denominations summing to a specific amount."""
        self.assertEqual(solution([1000, 2000, 3000], 5000), 5)

    def test_many_duplicates(self):
        """A large list of identical coins should still return a single combination."""
        self.assertEqual(solution([1] * 300, 3), 1)

    def test_reference_dp_on_large_input(self):
        """Validate the implementation against a reference DP for a large input set."""
        coins = list(range(1, 301))          # 300 unique coin denominations 1..300
        amount = 5000
        expected = self._compute_expected_dp(coins, amount)
        result = solution(coins, amount)
        self.assertEqual(result, expected)
        self.assertTrue(0 <= result <= (2**31 - 1))

    # ------------------------------------------------------------------
    # Helper method: a reference implementation for computing expected DP.
    # ------------------------------------------------------------------
    def _compute_expected_dp(self, coins, amount):
        """Compute the number of combinations using a straightforward DP"""
        dp = [0] * (amount + 1)
        dp[0] = 1
        for coin in coins:
            for value in range(coin, amount + 1):
                dp[value] += dp[value - coin]
        return dp[amount]

if __name__ == '__main__':
    unittest.main()

