def solution(nums):
    """
    Recursively sums all positive integers in the input list.
    Raises ValueError if any negative integer is encountered.

    Parameters:
        nums (list of int): List of integers (1 <= len(nums) <= 100, each in [-1000, 1000]).

    Returns:
        int: Sum of all positive integers in `nums`.

    Raises:
        ValueError: If a negative integer is found in the list.
    """
    def _sum_pos(lst):
        if not lst:
            return 0
        first, rest = lst[0], lst[1:]
        if first < 0:
            raise ValueError("Negative integers are not allowed.")
        return (first if first > 0 else 0) + _sum_pos(rest)

    return _sum_pos(nums)

