def solution():
    """
    Computes the minimum path sum from the top-left to the bottom-right
    of a grid, moving only right or down, and only through cells
    whose cost is even. If no valid path exists, outputs 0.
    """
    import sys
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    try:
        m = int(next(it))
        n = int(next(it))
    except StopIteration:
        return

    # Read grid values
    grid = [[0]*n for _ in range(m)]
    for i in range(m):
        for j in range(n):
            try:
                grid[i][j] = int(next(it))
            except StopIteration:
                grid[i][j] = 0  # default if input is incomplete

    INF = 10**15  # large enough to represent unreachable cells

    # dp[i][j] will hold the minimal cost to reach cell (i,j)
    dp = [[INF]*n for _ in range(m)]

    # Initialize the starting cell
    if grid[0][0] % 2 == 0:
        dp[0][0] = grid[0][0]

    # Fill first row
    for j in range(1, n):
        if grid[0][j] % 2 == 0 and dp[0][j-1] != INF:
            dp[0][j] = dp[0][j-1] + grid[0][j]

    # Fill first column
    for i in range(1, m):
        if grid[i][0] % 2 == 0 and dp[i-1][0] != INF:
            dp[i][0] = dp[i-1][0] + grid[i][0]

    # Fill the rest of the grid
    for i in range(1, m):
        for j in range(1, n):
            if grid[i][j] % 2 != 0:
                continue  # cannot step on odd-cost cells
            best = INF
            if dp[i-1][j] < best:
                best = dp[i-1][j]
            if dp[i][j-1] < best:
                best = dp[i][j-1]
            if best != INF:
                dp[i][j] = best + grid[i][j]

    result = dp[m-1][n-1]
    if result == INF:
        result = 0
    print(result)

