def solution(arr):
    """
    Return the maximum even sum of any contiguous subarray that contains at least one
    positive integer. If no such subarray exists, return -1.

    The algorithm keeps four states for subarrays ending at the current index:
        even_pos  – even sum, contains at least one positive number
        odd_pos   – odd sum, contains at least one positive number
        even_nop  – even sum, contains no positive numbers
        odd_nop   – odd sum, contains no positive numbers

    While iterating, we consider starting a new subarray with the current element
    and extending each existing state with the current element. The global maximum
    for even_pos is tracked separately. Complexity: O(n) time, O(1) space.
    """
    if not arr:
        return -1

    NEG_INF = -10 ** 18

    even_pos = odd_pos = even_nop = odd_nop = NEG_INF
    best_even_pos_global = NEG_INF

    for x in arr:
        new_even_pos = new_odd_pos = new_even_nop = new_odd_nop = NEG_INF

        parity = 0 if x % 2 == 0 else 1
        has_pos = x > 0
        if has_pos:
            if parity == 0:
                new_even_pos = max(new_even_pos, x)
            else:
                new_odd_pos = max(new_odd_pos, x)
        else:
            if parity == 0:
                new_even_nop = max(new_even_nop, x)
            else:
                new_odd_nop = max(new_odd_nop, x)

        prev_states = [
            (even_pos, True, 0),
            (odd_pos, True, 1),
            (even_nop, False, 0),
            (odd_nop, False, 1)
        ]

        for prev_sum, prev_has_pos, prev_parity in prev_states:
            if prev_sum == NEG_INF:
                continue
            new_sum = prev_sum + x
            new_parity = (prev_parity + (x % 2)) % 2
            new_has_pos = prev_has_pos or (x > 0)

            if new_has_pos:
                if new_parity == 0:
                    new_even_pos = max(new_even_pos, new_sum)
                else:
                    new_odd_pos = max(new_odd_pos, new_sum)
            else:
                if new_parity == 0:
                    new_even_nop = max(new_even_nop, new_sum)
                else:
                    new_odd_nop = max(new_odd_nop, new_sum)

        even_pos, odd_pos, even_nop, odd_nop = (
            new_even_pos,
            new_odd_pos,
            new_even_nop,
            new_odd_nop
        )

        if even_pos > best_even_pos_global:
            best_even_pos_global = even_pos

    return -1 if best_even_pos_global == NEG_INF else best_even_pos_global

def solution(arr):
    """
    Find the maximum even sum of any contiguous subarray that contains at least
    one positive integer.  The sum itself must be positive (greater than zero).
    If no such subarray exists, return -1.

    The algorithm keeps four states for subarrays ending at the current index:
        even_pos  – even sum, contains at least one positive number
        odd_pos   – odd sum, contains at least one positive number
        even_nop  – even sum, contains no positive numbers
        odd_nop   – odd sum, contains no positive numbers

    While iterating, we consider starting a new subarray with the current element
    and extending each existing state with the current element.  The global best
    even sum that is *positive* and has at least one positive element is tracked.
    Complexity: O(n) time, O(1) space.
    """
    if not arr:
        return -1

    NEG_INF = -10 ** 18

    even_pos = odd_pos = even_nop = odd_nop = NEG_INF
    best_even_pos_global = None

    for x in arr:
        new_even_pos = new_odd_pos = new_even_nop = new_odd_nop = NEG_INF

        parity = 0 if x % 2 == 0 else 1
        has_pos = x > 0

        # Start a new subarray consisting of only x
        if has_pos:
            if parity == 0:
                new_even_pos = max(new_even_pos, x)
            else:
                new_odd_pos = max(new_odd_pos, x)
        else:
            if parity == 0:
                new_even_nop = max(new_even_nop, x)
            else:
                new_odd_nop = max(new_odd_nop, x)

        # Extend previous states
        prev_states = [
            (even_pos, True, 0),
            (odd_pos, True, 1),
            (even_nop, False, 0),
            (odd_nop, False, 1)
        ]

        for prev_sum, prev_has_pos, prev_parity in prev_states:
            if prev_sum == NEG_INF:
                continue
            new_sum = prev_sum + x
            new_parity = (prev_parity + (x % 2)) % 2
            new_has_pos = prev_has_pos or (x > 0)

            if new_has_pos:
                if new_parity == 0:
                    new_even_pos = max(new_even_pos, new_sum)
                else:
                    new_odd_pos = max(new_odd_pos, new_sum)
            else:
                if new_parity == 0:
                    new_even_nop = max(new_even_nop, new_sum)
                else:
                    new_odd_nop = max(new_odd_nop, new_sum)

        # Update states for next iteration
        even_pos, odd_pos, even_nop, odd_nop = (
            new_even_pos,
            new_odd_pos,
            new_even_nop,
            new_odd_nop
        )

        # Record best positive even sum with at least one positive number
        if even_pos > 0:
            if best_even_pos_global is None or even_pos > best_even_pos_global:
                best_even_pos_global = even_pos

    return best_even_pos_global if best_even_pos_global is not None else -1

