def solution(arr):
    """
    Given a list of integers, returns the number of unique index pairs (i, j)
    with i < j such that the sum arr[i] + arr[j] is even.
    """
    # Count how many numbers are even and how many are odd
    even_count = 0
    odd_count = 0
    for num in arr:
        if num % 2 == 0:
            even_count += 1
        else:
            odd_count += 1

    # Helper to compute "n choose 2" (pairs from a group of n)
    def comb2(x):
        return x * (x - 1) // 2

    # A pair sums to an even number if both numbers are even or both are odd
    return comb2(even_count) + comb2(odd_count)

def solution():
    """
    Search for a target in a 2D matrix that is sorted such that each row is sorted
    ascending and the first element of each row is greater than the last element
    of the previous row.  The matrix can be treated as a flattened sorted array.
    This function reads input from standard input:
        - First line: two integers m and n (rows and columns)
        - Next m lines: each containing n integers
        - Last line: the target integer
    It returns a tuple (row_index, col_index) if the target is found, otherwise (-1, -1).
    """
    import sys

    data = sys.stdin.read().strip().split()
    if not data:
        return (-1, -1)

    it = iter(data)
    try:
        m = int(next(it))
        n = int(next(it))
    except StopIteration:
        return (-1, -1)

    matrix = []
    for _ in range(m):
        row = []
        for _ in range(n):
            try:
                row.append(int(next(it)))
            except StopIteration:
                row.append(0)  # placeholder; will not be used if input is malformed
        matrix.append(row)

    try:
        target = int(next(it))
    except StopIteration:
        target = None

    # Edge case: if target is None, cannot search
    if target is None:
        return (-1, -1)

    # Binary search on the flattened view of the matrix
    left, right = 0, m * n - 1
    while left <= right:
        mid = (left + right) // 2
        row, col = divmod(mid, n)
        value = matrix[row][col]
        if value == target:
            return (row, col)
        elif value < target:
            left = mid + 1
        else:
            right = mid - 1

    # Target not found
    return (-1, -1)

