def solution(arr, target):
    """
    Recursive binary search with robust error handling.

    Parameters:
        arr (list[int]): Sorted list of integers.
        target (int): Integer value to search for.

    Returns:
        int | str: Index of target if found; otherwise an error message.
    """
    # ----------------------------
    # Input validation
    # ----------------------------
    # Check that arr is a list
    if not isinstance(arr, list):
        return "Invalid input"

    # Check that target is an integer
    if not isinstance(target, int):
        return "Invalid input"

    # Check that every element in arr is an integer and that arr is sorted ascending
    # This loop also ensures the array is not too deep for recursion in pathological cases.
    prev = None
    for elem in arr:
        if not isinstance(elem, int):
            return "Invalid input"
        if prev is not None and elem < prev:
            return "Invalid input"
        prev = elem

    # ----------------------------
    # Recursive search
    # ----------------------------
    def binary_search(low, high):
        if low > high:
            return "Target not found"
        mid = (low + high) // 2
        mid_val = arr[mid]
        if mid_val == target:
            return mid
        elif target < mid_val:
            return binary_search(low, mid - 1)
        else:
            return binary_search(mid + 1, high)

    return binary_search(0, len(arr) - 1)

