        height = entry['height']
        # Accept both int and float for height but enforce positivity
        if not isinstance(height, (int, float)) or height <= 0:
            return error_msg('height', entry)

    # All entries are valid; perform sorting
    try:
        # Ensure sort_keys contain only allowed keys
        allowed_keys = {'name', 'age', 'height'}
        if not all(key in allowed_keys for key in sort_keys):
            raise ValueError("Invalid sort key(s) provided.")
        sorted_data = sorted(data, key=lambda x: tuple(x[k] for k in sort_keys))
    except Exception as e:
        # Catch any unforeseen errors during sorting
        return f"Error: {str(e)}. Unsorted list returned."

    return sorted_data

