def solution(n: int):
    """
    Generate all structurally unique BSTs that store values 1 to n.
    Returns a list of TreeNode root objects (or an empty list if n == 0).
    Raises ValueError for n < 0 or n > 8 (per problem constraints).
    """
    # Validate input according to problem constraints
    if n < 0:
        raise ValueError("n must be non‑negative")
    if n > 8:
        raise ValueError("n must not exceed 8")

    # If no nodes, return an empty list as required by the tests
    if n == 0:
        return []

    # Definition for a binary tree node
    class TreeNode:
        __slots__ = ("val", "left", "right")

        def __init__(self, val: int = 0, left: 'TreeNode' = None, right: 'TreeNode' = None):
            self.val = val
            self.left = left
            self.right = right

    from functools import lru_cache
    from typing import List

    @lru_cache(maxsize=None)
    def generate(start: int, end: int) -> List[TreeNode]:
        """
        Recursively generate all BSTs with values in the inclusive range [start, end].
        Uses memoization to avoid recomputation.
        """
        trees: List[TreeNode] = []

        # Base case: empty subtree
        if start > end:
            return [None]

        # Try every number in range as root
        for root_val in range(start, end + 1):
            left_subtrees = generate(start, root_val - 1)
            right_subtrees = generate(root_val + 1, end)

            for left in left_subtrees:
                for right in right_subtrees:
                    trees.append(TreeNode(root_val, left, right))

        return trees

    return generate(1, n)

def solution():
    import sys, random
    sys.setrecursionlimit(1 << 25)
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    # Treap node definition
    class Node:
        __slots__ = ("key", "prio", "cnt", "left", "right")
        def __init__(self, key):
            self.key = key
            self.prio = random.randrange(1 << 30)
            self.cnt = 1
            self.left = None
            self.right = None

    # Merge two treaps l and r, all keys in l <= keys in r
    def merge(l, r):
        if not l or not r:
            return l or r
        if l.prio > r.prio:
            l.right = merge(l.right, r)
            return l
        else:
            r.left = merge(l, r.left)
            return r

    # Split treap t into (l, r) where keys in l <= key, r > key
    def split(t, key):
        if not t:
            return (None, None)
        if key < t.key:
            l, r = split(t.left, key)
            t.left = r
            return (l, t)
        else:
            l, r = split(t.right, key)
            t.right = l
            return (t, r)

    # Insert key into treap t
    def insert(t, key):
        if not t:
            return Node(key)
        if key == t.key:
            t.cnt += 1
            return t
        if key < t.key:
            t.left = insert(t.left, key)
            if t.left.prio > t.prio:
                # rotate right
                l = t.left
                t.left = l.right
                l.right = t
                return l
        else:
            t.right = insert(t.right, key)
            if t.right.prio > t.prio:
                # rotate left
                r = t.right
                t.right = r.left
                r.left = t
                return r
        return t

    # Delete one occurrence of key from treap t
    def delete(t, key):
        if not t:
            return None
        if key == t.key:
            if t.cnt > 1:
                t.cnt -= 1
                return t
            # remove node
            return merge(t.left, t.right)
        elif key < t.key:
            t.left = delete(t.left, key)
        else:
            t.right = delete(t.right, key)
        return t

    # In-order traversal collecting nodes that satisfy filter_func
    def inorder_collect(node, filter_func, res):
        if not node:
            return
        inorder_collect(node.left, filter_func, res)
        if filter_func(node.key):
            res.extend([str(node.key)] * node.cnt)
        inorder_collect(node.right, filter_func, res)

    root = None
    out_lines = []

    for _ in range(n):
        line = next(it).strip()
        if not line:
            continue
        parts = line.split()
        cmd = parts[0]
        if cmd == "INSERT":
            x = int(parts[1])
            root = insert(root, x)
        elif cmd == "DELETE":
            x = int(parts[1])
            root = delete(root, x)
        elif cmd == "SEARCH":
            cond = parts[1]
            if cond == "EVEN":
                res = []
                inorder_collect(root, lambda k: k % 2 == 0, res)
                if res:
                    out_lines.extend(res)
                else:
                    out_lines.append("EMPTY")
            elif cond == "ODD":
                res = []
                inorder_collect(root, lambda k: k % 2 == 1, res)
                if res:
                    out_lines.extend(res)
                else:
                    out_lines.append("EMPTY")
            elif cond == "GREATER":
                x = int(parts[2])
                # split root into <=x and >x
                left, right = split(root, x)
                res = []
                inorder_collect(right, lambda k: True, res)
                # merge back
                root = merge(left, right)
                if res:
                    out_lines.extend(res)
                else:
                    out_lines.append("EMPTY")

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solution()

