def solution(arr, exprs):
    """
    Return the maximum value among conditional expressions that evaluate to True
    for the given array `arr`. Each expression is a string of the form:
        "a[i] <op> a[j] then value"
    where <op> can be one of: <, <=, >, >=, ==, !=.
    The expression may contain arbitrary spaces or no spaces at all.
    If no expression is true, return 0.
    """
    import re

    # Precompile regex to extract indices and operator
    # Handles optional whitespace between parts
    cond_pattern = re.compile(
        r'a\[(\d+)\]\s*(<=|>=|==|!=|<|>)\s*a\[(\d+)\]',
        re.IGNORECASE
    )

    best = 0  # default when no expression is true

    for expr in exprs:
        # Split into condition part and value part at the first occurrence of 'then'
        if 'then' not in expr:
            continue
        cond_part, val_part = expr.split('then', 1)
        # Parse the value (strip any surrounding whitespace and quotes)
        try:
            val = int(val_part.strip().replace('"', '').replace("'", ""))
        except ValueError:
            # If value is not an integer, skip this expression
            continue

        # Find indices and operator in the condition part
        m = cond_pattern.search(cond_part)
        if not m:
            continue

        i, op, j = m.group(1), m.group(2), m.group(3)
        i, j = int(i), int(j)

        # Validate indices are within bounds of the array
        if not (0 <= i < len(arr)) or not (0 <= j < len(arr)):
            continue

        a, b = arr[i], arr[j]

        # Evaluate the condition
        cond_true = False
        if op == '<':
            cond_true = a < b
        elif op == '<=':
            cond_true = a <= b
        elif op == '>':
            cond_true = a > b
        elif op == '>=':
            cond_true = a >= b
        elif op == '==':
            cond_true = a == b
        elif op == '!=':
            cond_true = a != b

        if cond_true:
            if val > best:
                best = val

    return best

