def solution() -> None:
    """
    Reads a matrix and a target value from standard input, then recursively searches
    for the target. If found, prints the zero‑indexed row and column. If not found,
    raises a ValueError with the message "Value Not Found".

    The search is performed using depth‑first recursion while keeping track of
    visited cells to avoid revisiting and infinite loops. The recursion depth
    limit is increased to safely handle the worst case of a 100x100 matrix
    (10,000 cells).
    """
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    try:
        m = int(next(it))
        n = int(next(it))
    except StopIteration:
        return

    matrix: List[List[int]] = []
    for _ in range(m):
        row = [int(next(it)) for _ in range(n)]
        matrix.append(row)

    try:
        target = int(next(it))
    except StopIteration:
        return

    sys.setrecursionlimit(max(1000, m * n + 100))  # safety for deep recursion

    visited: Set[Tuple[int, int]] = set()

    def dfs(r: int, c: int) -> Tuple[int, int]:
        """
        Recursively search for the target starting from cell (r, c).
        Returns the coordinates if found, otherwise raises ValueError.
        """
        # Boundary check
        if r < 0 or r >= m or c < 0 or c >= n:
            raise ValueError("Value Not Found")
        if (r, c) in visited:
            raise ValueError("Value Not Found")
        visited.add((r, c))

        if matrix[r][c] == target:
            return (r, c)

        # Explore neighbors: up, down, left, right
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            try:
                return dfs(nr, nc)
            except ValueError:
                continue

        # If all neighbors exhausted and target not found
        raise ValueError("Value Not Found")

    try:
        row, col = dfs(0, 0)
        print(row, col)
    except ValueError as e:
        # As per problem statement, raise a custom error message
        raise ValueError(str(e))

