def solution():
    import sys

    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    arr = data[1:n+1]

    # Helper to maintain max-heap property
    def sift_down(a, start, end):
        root = start
        while True:
            child = 2 * root + 1
            if child > end:
                break
            # If right child exists and is greater, use it
            if child + 1 <= end and a[child] < a[child + 1]:
                child += 1
            if a[root] < a[child]:
                a[root], a[child] = a[child], a[root]
                root = child
            else:
                break

    # Build max‑heap
    N = n
    for i in range((N - 2) // 2, -1, -1):
        sift_down(arr, i, N - 1)

    # Extract elements to sort ascending
    for end in range(N - 1, 0, -1):
        arr[0], arr[end] = arr[end], arr[0]
        sift_down(arr, 0, end - 1)

    # Reverse to get descending order
    arr.reverse()

    sys.stdout.write(' '.join(map(str, arr)))

