def solution():
    import sys

    data = list(map(int, sys.stdin.read().strip().split()))
    if not data:
        return
    n = data[0]
    arr = data[1:1 + n]

    # Coordinate compression for arbitrary integer values
    sorted_vals = sorted(set(arr))
    idx_map = {v: i + 1 for i, v in enumerate(sorted_vals)}
    m = len(sorted_vals)

    # Fenwick Tree for range maximum query
    bit = [0] * (m + 1)

    def bit_query(i):
        """Return max in prefix [1, i]."""
        res = 0
        while i > 0:
            if bit[i] > res:
                res = bit[i]
            i -= i & -i
        return res

    def bit_update(i, val):
        """Update position i with maximum value."""
        while i <= m:
            if val > bit[i]:
                bit[i] = val
            i += i & -i

    max_sum = 0
    for a in arr:
        pos = idx_map[a]
        best = bit_query(pos - 1) if pos > 1 else 0
        candidate = best + a
        if candidate > max_sum:
            max_sum = candidate
        bit_update(pos, candidate)

    sys.stdout.write(str(max_sum))

