def solution():
    """
    Reads an integer n followed by n integers (array elements).
    Computes the maximum possible sum of a strictly increasing subsequence
    using dynamic programming (O(n^2) time, O(n) space).
    Returns the maximum sum as an integer.
    """
    import sys, re

    # Read entire input and extract all integers
    data = sys.stdin.read()
    nums = list(map(int, re.findall(r'\d+', data)))
    if not nums:
        return 0  # no input

    n = nums[0]
    arr = nums[1:1 + n]
    if not arr:
        return 0

    # dp[i] = maximum sum of an increasing subsequence ending at index i
    dp = arr[:]  # start with each element alone
    for i in range(n):
        ai = arr[i]
        for j in range(i):
            if arr[j] < ai:
                if dp[j] + ai > dp[i]:
                    dp[i] = dp[j] + ai

    return max(dp)

