        elif cmd == "REMOVE":
            x = int(parts[1])
            if x in data:
                data.remove(x)
            out_lines.append("Operation successful")
        elif cmd == "MAX":
            if data:
                out_lines.append(str(max(data)))
            else:
                out_lines.append(str(-1))
        elif cmd == "SORT":
            order = parts[1]
            if data:
                sorted_list = sorted(data) if order == "ASC" else sorted(data, reverse=True)
                out_lines.append(' '.join(map(str, sorted_list)))
            else:
                out_lines.append('')
        elif cmd == "CONDITIONAL":
            # parts: ["CONDITIONAL", "SORT", "EVEN"] or ["CONDITIONAL", "SORT", "ODD"]
            criteria = parts[2]
            if criteria == "EVEN":
                filtered = [x for x in data if x % 2 == 0]
            else:  # ODD
                filtered = [x for x in data if x % 2 == 1]
            if filtered:
                out_lines.append(' '.join(map(str, sorted(filtered))))
            else:
                out_lines.append('')
        else:
            # Unknown command, skip
            out_lines.append("Operation successful")
    sys.stdout.write("\n".join(out_lines))

