    try:
        n = int(data)
    except ValueError:
        # Invalid input; nothing to output
        return

    # Handle evenness first
    if n % 2 == 0:
        print("Even")
        return

    # At this point, n is odd
    # Special case: 1 is odd but not prime nor composite
    if n == 1:
        print("Odd")
        return

    # Primality test using trial division up to sqrt(n)
    def is_prime(x: int) -> bool:
        if x <= 1:
            return False
        if x <= 3:
            return True
        if x % 3 == 0:
            return False
        i = 5
        while i * i <= x:
            if x % i == 0 or x % (i + 2) == 0:
                return False
            i += 6
        return True

