def solution(arr, target):
    """
    Recursive binary search on a sorted array with comprehensive error handling.

    Parameters:
    - arr (list[int]): Sorted list of integers (ascending order).
    - target (int): The integer value to locate within the array.

    Returns:
    - int: Index of the target value in arr.

    Raises:
    - ValueNotFoundError: If the target cannot be found.
    - InvalidInputError: If arr is not sorted or target is not an integer.
    """
    # Custom exception definitions
    class ValueNotFoundError(Exception):
        """Raised when the target value is not present in the array."""
        pass

    class InvalidInputError(Exception):
        """Raised when input validation fails."""
        pass

    # ---- Input validation ----
    # Target must be an integer
    if not isinstance(target, int):
        raise InvalidInputError("Invalid input provided.")

    # Array must be a list (or sequence) of comparable items
    if not isinstance(arr, list):
        raise InvalidInputError("Invalid input provided.")

    # Empty array is still considered sorted, but will trigger not-found later
    # Ensure the array is sorted in ascending order
    if any(arr[i] > arr[i + 1] for i in range(len(arr) - 1)):
        raise InvalidInputError("Invalid input provided.")

    # ---- Recursive binary search helper ----
    def _binary_search(low: int, high: int) -> int:
        """Recursively search for target in arr[low:high+1]."""
        if low > high:
            # Terminates when subarray is empty → target not found
            raise ValueNotFoundError("Value not found in the array.")

        mid = (low + high) // 2
        mid_val = arr[mid]

        if mid_val == target:
            return mid
        elif mid_val < target:
            return _binary_search(mid + 1, high)
        else:
            return _binary_search(low, mid - 1)

    # ---- Execution ----
    return _binary_search(0, len(arr) - 1)

