def solution(items, sort_keys=None):
    """
    Validate and sort a list of items.

    Parameters
    ----------
    items : list[dict]
        The list of items to validate and sort.
    sort_keys : list[str] | None, optional
        Keys used for sorting.  If None or an empty list, the original order is preserved.

    Returns
    -------
    list[dict] | list[str]
        Sorted items if all are valid, otherwise a list of error messages.
    """
    errors = []

    # Validate each item
    for idx, item in enumerate(items):
        # Name must be a string
        if not isinstance(item.get("name"), str):
            errors.append(f"Error: Name for item at index {idx} is not a string.")

        # Value must be an integer
        if not isinstance(item.get("value"), int):
            name = item.get("name", f"Item{idx}")
            errors.append(f"Error: Value for '{name}' is not an integer.")

        # Category must be a string
        if not isinstance(item.get("category"), str):
            name = item.get("name", f"Item{idx}")
            errors.append(f"Error: Category for '{name}' is not a string.")

    # If any errors were found, return them
    if errors:
        return errors

    # No errors: perform sorting if requested
    if sort_keys is None or not sort_keys:
        return items

    # All items are valid; perform sorting
    return sorted(items, key=lambda it: tuple(it[k] for k in sort_keys))


