def solution(arr, target):
    """
    Recursive binary search with error handling.

    Parameters
    ----------
    arr : list[int]
        Sorted ascending list of distinct integers.
    target : int
        Value to search for.

    Returns
    -------
    int | str
        Index of `target` in `arr` if found, otherwise
        "Element not found". If `arr` is not a valid list,
        returns "Invalid input".
    """
    # Validate input array
    if arr is None or not isinstance(arr, list):
        return "Invalid input"
    n = len(arr)
    if n == 0:
        return "Element not found"

    # Helper recursive function
    def _binary_search(low, high):
        if low > high:
            return "Element not found"
        mid = (low + high) // 2
        mid_val = arr[mid]
        if mid_val == target:
            return mid
        elif mid_val < target:
            return _binary_search(mid + 1, high)
        else:
            return _binary_search(low, mid - 1)

    return _binary_search(0, n - 1)

def solution(arr, target):
    """
    Recursive binary search with validation of sorted order.

    Parameters
    ----------
    arr : list[int]
        Sorted ascending list of distinct integers.
    target : int
        Value to search for.

    Returns
    -------
    int | str
        Index of `target` in `arr` if found, otherwise
        "Element not found". If `arr` is not a valid list,
        returns "Invalid input". If `arr` is not strictly sorted
        ascendingly, also returns "Element not found".
    """
    # Validate that arr is a list
    if arr is None or not isinstance(arr, list):
        return "Invalid input"

    n = len(arr)
    if n == 0:
        return "Element not found"

    # Verify that the array is strictly sorted in ascending order.
    # If not, we must return "Element not found" as per test requirements.
    for i in range(n - 1):
        if arr[i] >= arr[i + 1]:
            return "Element not found"

    def _binary_search(low, high):
        """Recursive helper that assumes arr[low:high+1] is sorted."""
        if low > high:
            return "Element not found"
        mid = (low + high) // 2
        mid_val = arr[mid]
        if mid_val == target:
            return mid
        elif mid_val < target:
            return _binary_search(mid + 1, high)
        else:
            return _binary_search(low, mid - 1)

    return _binary_search(0, n - 1)

def solution(n, arr):
    # Edge case: empty array – not expected, but handled for safety
    if n == 0:
        return (0, 1)

    # Minimum and maximum values of the array
    mn = min(arr)
    mx = max(arr)

    # The smallest possible sum of absolute differences between
    # consecutive elements is always the difference between max and min.
    min_sum = mx - mn

    # Count of optimal arrangements
    # If all elements are equal, only one arrangement exists.
    # Otherwise, both ascending and descending orders achieve the minimum.
    if mn == mx:
        count = 1
    else:
        count = 2

    return (min_sum, count)

