        """Single coin denomination equal to amount."""
        self.assertEqual(solution([7], 7), 1)

    def test_single_coin_less_than_amount(self):
        """Single coin denomination less than amount should yield zero combinations."""
        self.assertEqual(solution([5], 3), 0)

    def test_duplicate_denominations(self):
        """Duplicate denominations should not affect combination count."""
        self.assertEqual(solution([1, 1, 2], 3), 2)  # 1+1+1, 1+2

