        self.assertEqual(solution(coins, 20), expected_partitions)

    def test_computed_expected(self):
        """Validate function against a reference DP implementation for random cases."""
        def reference_dp(coins, amount):
            dp = [0] * (amount + 1)
            dp[0] = 1
            for coin in coins:
                for amt in range(coin, amount + 1):
                    dp[amt] += dp[amt - coin]
            return dp[amount]

        coins = [1, 3, 4, 5]
        amount = 100
        expected = reference_dp(coins, amount)
        result = solution(coins, amount)
        self.assertEqual(result, expected)

