def solution(n, arr, k):
    """
    Sorts a list of integers and performs a binary search for a target value.
    Returns the index of the target in the sorted list, -1 if not found,
    or a string describing an error for invalid input.
    """
    # ----- Input validation -----
    # Validate n
    if not isinstance(n, int):
        return "Error: n must be an integer."
    if n < 1 or n > 10**6:
        return "Error: n must be between 1 and 10^6."

    # Validate arr
    if not isinstance(arr, (list, tuple)):
        return "Error: list must be a list or tuple of integers."
    if len(arr) != n:
        return f"Error: list length ({len(arr)}) does not match n ({n})."

    # Validate each element in arr
    for idx, val in enumerate(arr):
        if not isinstance(val, int):
            return f"Error: element at index {idx} is not an integer."
        if val < -10**9 or val > 10**9:
            return f"Error: element at index {idx} out of allowed range."

    # Validate k
    if not isinstance(k, int):
        return "Error: k must be an integer."
    if k < -10**9 or k > 10**9:
        return "Error: k out of allowed range."

    # ----- Sorting -----
    sorted_arr = sorted(arr)  # Timsort: O(n log n)

    # ----- Binary search using bisect -----
    import bisect
    pos = bisect.bisect_left(sorted_arr, k)
    if pos < len(sorted_arr) and sorted_arr[pos] == k:
        return pos  # 0‑based index in the sorted list
    else:
        return -1

