    def dfs(depth: int, current_sum: int):
        """Recursively simulate the nested loops."""
        if depth == n:
            # All loops finished; add the sum if it does not exceed 100.
            if current_sum <= 100:
                result.append(current_sum)
            return

        loop_limit = n if depth == 0 else m
        for i in range(loop_limit):
            dfs(depth + 1, current_sum + i)

    dfs(0, 0)

    # Output the result list as the required format.
    print(result)

