def solution(initial, ops):
    # Coordinate compression: collect all values that may appear
    values = list(initial)
    parsed_ops = []
    for op_str in ops:
        parts = op_str.strip().split()
        if not parts:
            continue
        op = parts[0].upper()
        # Extract integer; handle malformed lines gracefully
        val = None
        for token in parts[1:]:
            try:
                val = int(token)
                break
            except ValueError:
                continue
        if val is None:
            continue
        parsed_ops.append((op, val))
        values.append(val)

    # Sort unique values for compression
    uniq = sorted(set(values))
    idx_of = {v: i for i, v in enumerate(uniq)}
    size = len(uniq)

    # Fenwick tree (Binary Indexed Tree) for prefix sums
    fenwick = [0] * (size + 1)

    def fenwick_update(i, delta):
        i += 1  # convert to 1-based index
        while i <= size:
            fenwick[i] += delta
            i += i & -i

    def fenwick_query(i):
        """Return sum of counts in [0..i] (inclusive)."""
        i += 1
        s = 0
        while i > 0:
            s += fenwick[i]
            i -= i & -i
        return s

    # Count map for current multiplicity of each value
    count_map = {}
    for v in initial:
        idx = idx_of[v]
        fenwick_update(idx, 1)
        count_map[v] = count_map.get(v, 0) + 1

    outputs = []
    for op, val in parsed_ops:
        if op == "INSERT":
            idx = idx_of[val]
            fenwick_update(idx, 1)
            count_map[val] = count_map.get(val, 0) + 1
            outputs.append("INSERT successful")
        elif op == "DELETE":
            cur = count_map.get(val, 0)
            if cur:
                idx = idx_of[val]
                fenwick_update(idx, -cur)
                count_map[val] = 0
            outputs.append("DELETE successful")
        elif op == "SEARCH":
            cur = count_map.get(val, 0)
            if cur:
                idx = idx_of[val]
                before = fenwick_query(idx - 1) if idx > 0 else 0
                outputs.append(str(before))
            else:
                # As per specification, searching a non‑present value returns 0
                outputs.append("0")
        else:
            # Ignore unknown commands
            continue

    return outputs

