        op = parts[0].upper()
        if len(parts) < 2:
            # Malformed operation, ignore
            continue
        try:
            val = int(parts[1])
        except ValueError:
            continue

        if op == "INSERT":
            bisect.insort_left(arr, val)
            outputs.append("INSERT successful")
        elif op == "DELETE":
            idx = bisect.bisect_left(arr, val)
            if idx < len(arr) and arr[idx] == val:
                arr.pop(idx)
            outputs.append("DELETE successful")
        elif op == "SEARCH":
            idx = bisect.bisect_left(arr, val)
